#include <iostream>
#include <map>
#include <vector>
#include <functional>
#include <string>
using namespace std;

template<typename T>
class EventBus {
    map<string, vector<function<void(T)>>> listeners;
public:
    void on(const string& event, function<void(T)> cb) {
        listeners[event].push_back(cb);
    }
    void emit(const string& event, T data) {
        for (auto& cb : listeners[event]) cb(data);
    }
};

int main() {
    EventBus<string> bus;
    bus.on("login", [](string user) { cout << "Login: " << user << endl; });
    bus.on("logout", [](string user) { cout << "Logout: " << user << endl; });
    bus.emit("login", "Alice");
    bus.emit("logout", "Bob");
    return 0;
}
